import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z4 } from "npm:zod@^3.25.76";
var list_features_default = defineTool4({
  name: "list_features",
  title: "List features",
  description: "List ShadowTalk AI features with their category, in-app route and a short description. Optionally filter by keyword or category.",
  inputSchema: {
    query: z4.string().optional().describe("Free-text keyword to filter features by name or description."),
    category: z4.string().optional().describe("Filter by category, e.g. chat, research, security, code, privacy, platform.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, category }) => {
    const q = query?.trim().toLowerCase();
    const cat = category?.trim().toLowerCase();
    const matches = FEATURES.filter((feature) => {
      const inCategory = !cat || feature.category.toLowerCase() === cat;
      const inQuery = !q || feature.name.toLowerCase().includes(q) || feature.description.toLowerCase().includes(q);
      return inCategory && inQuery;
    });
    if (matches.length === 0) {
      return {
        content: [
          {
            type: "text",
            text: `No features matched. Available categories: ${[
              ...new Set(FEATURES.map((f) => f.category))
            ].join(", ")}`
          }
        ],
        structuredContent: { features: [] }
      };
    }
    const text = matches.map(
      (f) => `- **${f.name}** (${f.category}) \u2014 ${f.description}
  ${PRODUCT.website}${f.route}`
    ).join("\n");
    return {
      content: [{ type: "text", text }],
      structuredContent: { features: matches }
    };
  }
});

